INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 41, 'theory', 'Quiz: protocols and generics');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 41, 0, 'Does Python check type hints while the program runs?', '["Yes, always", "Only for functions with a decorator", "No: they are read by editors and checkers (mypy, pyright)", "Only in debug mode"]', 2, 'Type hints are metadata; the interpreter does not enforce them.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 41, 1, 'How does a Protocol differ from an abstract class?', '["It does not", "Any object with the right methods fits - no inheritance required", "It forbids inheritance", "It works only at run time"]', 1, 'A protocol is structural subtyping: shape matters more than ancestry.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 41, 2, 'What does isinstance(obj, P) check for a @runtime_checkable protocol P?', '["Only that the needed attributes and methods exist, by name", "Method signatures and value types", "That obj inherits from P", "Nothing"]', 0, 'The check is shallow: signatures and types are left to the checker.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 41, 3, 'What does TypeVar give you in def first(items: Sequence[T]) -> T?', '["Restricts T to numbers only", "Makes the function slower", "Links the element type of the input to the type of the result", "Turns on checking at run time"]', 2, 'For a list of numbers the result is a number, for a list of strings a string; without TypeVar the link would be lost.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 41, 4, 'How should you hint the type of a parameter that a function only iterates over?', '["list[Any]", "object", "Any", "Iterable[T]"]', 3, 'Accept the least demanding type: then tuples, sets and generators fit.');
